/// <summary>
/// N.Freidenberger 16.05.2024
/// </summary>
public void registerDatasourceOnQueryingEvent()
{
    if (this.args().menuItemName() == menuItemDisplayStr(AVAKBVRequestTableMyOpenWorkerTileDisplay))
    {
        KCS_KBVRequestTable_DS.OnQueryExecuting +=eventhandler(this.parmFilterFormQueryEventHandler().applyFilter);
    }
}

/// <summary>
/// N.Freidenberger 16.05.2024
/// </summary>
public void onFilterChanged()
{
    if (this.args().menuItemName() == menuItemDisplayStr(AVAKBVRequestTableMyOpenWorkerTileDisplay))
    {
        KCS_KBVRequestTable_DS.executeQuery();
    }
}

/// <summary>
/// Allows to define defaults on the main data source in the quick create form.
/// </summary>
/// <param name = "_dirPartyEntityDS">Main data source in the quick create form, will be mapped to ContactPerson table.</param>
public void quickCreate_DirPartyEntity_InitValue(FormDataSource _dirPartyEntityDS)
{
    smmBusRelTable smmBusRelTable_loc = smmBusRelTable::findByParty(KCS_KBVInquirerOfTheRequest.DirPartyId);
    ContactPerson _contactPerson = _dirPartyEntityDS.cursor();

    _contactPerson.initFromArgsRecord(smmBusRelTable_loc);
}

/// <summary>
///    AVA <c>addFilterPaneRanges</c> method.
/// </summary>
public void addFilterPaneRanges()
{
    QueryBuildDataSource kcs_KBVRequestTableQBDS;

    kcs_KBVRequestTableQBDS = KCS_KBVRequestTable_DS.query().dataSourceName(KCS_KBVRequestTable_DS.name());

    SysQuery::findOrCreateRange(kcs_KBVRequestTableQBDS, fieldNum(KCS_KBVRequestTable, KCS_KBVRequestStatus));
    SysQuery::findOrCreateRange(kcs_KBVRequestTableQBDS, fieldNum(KCS_KBVRequestTable, KCS_KBVSmmSalesUnitIndoor));
    SysQuery::findOrCreateRange(kcs_KBVRequestTableQBDS, fieldNum(KCS_KBVRequestTable, AVAWorkerSalesTaker));
    SysQuery::findOrCreateRange(kcs_KBVRequestTableQBDS, fieldNum(KCS_KBVRequestTable, KCS_KBVModifiedBy));

    if(     frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableNotAssigned)
        ||  frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableNotAssignedDueDisplay)
        ||  frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableMyOpen))
    {
        kcs_KBVRequestTableQBDS.clearSortIndex();
        kcs_KBVRequestTableQBDS.addSortField(fieldNum(KCS_KBVRequestTable, KCS_KBVDeliveryDate),    SortOrder::Ascending);
        kcs_KBVRequestTableQBDS.addSortField(fieldNum(KCS_KBVRequestTable, KCS_KBVPriority),        SortOrder::Descending);
    }
}

/// <summary>
///    AVA <c>addCallerFilter</c> method.
/// </summary>
public void addCallerFilter()
{
    FormRun             locFormRunCaller;

    locFormRunCaller = frmArgs.caller();

    if (formHasMethod(locFormRunCaller, literalStr(getHCMWorkerFilterValue)))
    {
        frmHCMWorkerRecIdCallerFilter = locFormRunCaller.getHCMWorkerFilterValue();
    }
    if (!frmHCMWorkerRecIdCallerFilter)
    {
        frmHCMWorkerRecIdCallerFilter = frmHCMWorkerRecId;
    }
}

/// <summary>
///    AVA <c>addSecondaryDataAreaInfomation</c> method.
/// </summary>
public void addSecondaryDataAreaInfomation()
{
    KCS_KBVRequestTable locKCS_KBVRequestTable;
    //KCS_KBVRequestTable locKCS_KBVRequestTableCursor;

    if(     frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableNotAssigned)
        ||  frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableNotAssignedDueDisplay)
        ||  frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableMyOpen)                  )
    {
        SecondaryDataAreaInformation.visible(true);
    }
    if(frmAVASecondaryDataAreaIdBPRequests)
    {
        SecondaryDataAreaId.text(frmAVASecondaryDataAreaIdBPRequests);
        SecondaryKCS_KBVDeliveryDate.dateValue(dateNull());

        /*
        locKCS_KBVRequestTableCursor = KCS_KBVRequestTable_DS.cursor();
        if(locKCS_KBVRequestTableCursor.RecId)
        {
            changecompany(frmAVASecondaryDataAreaIdBPRequests)
            {
                locKCS_KBVRequestTable = null;

                if(frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableNotAssigned))
                {
                    select firstonly locKCS_KBVRequestTable
                    order by locKCS_KBVRequestTable.KCS_KBVDeliveryDate
                    where   locKCS_KBVRequestTable.KCS_KBVBuildingProjectID == locKCS_KBVRequestTableCursor.KCS_KBVBuildingProjectID
                        &&  locKCS_KBVRequestTable.AVAWorkerSalesTaker      == 0
                        &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus     == KCS_KBVRequestStatus::Created;
                }

                if(frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableMyOpen))
                {
                    select firstonly locKCS_KBVRequestTable
                    order by locKCS_KBVRequestTable.KCS_KBVDeliveryDate
                    where   locKCS_KBVRequestTable.KCS_KBVBuildingProjectID == locKCS_KBVRequestTableCursor.KCS_KBVBuildingProjectID
                        &&  locKCS_KBVRequestTable.AVAWorkerSalesTaker      == frmHCMWorkerRecId
                        &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus     != KCS_KBVRequestStatus::Refused
                        &&  locKCS_KBVRequestTable.KCS_KBVModifiedBy        == 0;
                }

                if(locKCS_KBVRequestTable.RecId)
                {
                    SecondaryKCS_KBVDeliveryDate.dateValue(locKCS_KBVRequestTable.KCS_KBVDeliveryDate);
                }
            }
        }
        */
        changecompany(frmAVASecondaryDataAreaIdBPRequests)
        {
            locKCS_KBVRequestTable = null;

            if(frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableMyOpen))
            {
                select firstonly locKCS_KBVRequestTable
                order by locKCS_KBVRequestTable.KCS_KBVDeliveryDate
                where   locKCS_KBVRequestTable.AVAWorkerSalesTaker      == frmHCMWorkerRecId
                    &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus     != KCS_KBVRequestStatus::Refused
                    &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus     != KCS_KBVRequestStatus::Answered
                    &&  locKCS_KBVRequestTable.KCS_KBVModifiedBy        == 0;
            }
            //if(frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableNotAssigned))
            else // allways calc date even it is not shown but relevant for take over of open requests in secondary company
            {
                select firstonly locKCS_KBVRequestTable
                order by locKCS_KBVRequestTable.KCS_KBVDeliveryDate
                where   locKCS_KBVRequestTable.AVAWorkerSalesTaker      == 0
                    &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus     != KCS_KBVRequestStatus::Refused;
            }

            if(locKCS_KBVRequestTable.RecId)
            {
                SecondaryKCS_KBVDeliveryDate.dateValue(locKCS_KBVRequestTable.KCS_KBVDeliveryDate);
            }
        }
    }
}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    super();

    frmAVASalesParameters               = AVASalesParameters::find();
    frmHCMWorkerRecId                   = HcmWorkerLookup::currentWorker();
    frmToday                            = AVAKBVBuildingProjectHelper::getToday();
    frmDataAreaId                       = CompanyInfo::find().DataArea; //curExt();
    frmAVASecondaryDataAreaIdBPRequests = frmAVASalesParameters.SecondaryDataAreaIdBPRequests;
    frmAVAForceSecondaryRequest         = frmAVASalesParameters.ForceSecondaryRequest;

    this.addFilterPaneRanges();

    this.addCallerFilter();

    KCS_KBVRequestTableFilterFields_KCS_KBVRequestStatus.enabled(true);
    KCS_KBVRequestTableFilterFields_KCS_KBVSmmSalesUnitIndoor.enabled(true);
    KCS_KBVRequestTableFilterFields_AVAWorkerSalesTaker.enabled(true);
    KCS_KBVRequestTableFilterFields_KCS_KBVModifiedBy.enabled(true);

    if(     frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableNotAssigned)
        ||  frmArgs.menuitemName() == menuItemDisplayStr(AVAKBVRequestTableNotAssignedDueDisplay)   )
    {
        KCS_KBVRequestTableFilterFields_KCS_KBVSmmSalesUnitIndoor.text(smmSalesUnit::avaGetSalesUnitCurrentWorkerIndoor().SalesUnitId);
        KCS_KBVRequestTableFilterFields_KCS_KBVSmmSalesUnitIndoor.modified();
    }

    this.addSecondaryDataAreaInfomation();
}

