/// <summary>
/// N.Freidenberger 24-07-2025
/// </summary>
public void close()
{
    super();
    if (this.args().caller() is FormRun)
    {
        FormRun  buildingProjectForm = this.args().caller();

        FormDataSource  buildingProjectDS = buildingProjectForm.dataSource('KCS_KBVBuildingProjectTable') ;
        if (buildingProjectDS)
        {
            KCS_KBVBuildingProjectTable     buildingProjectTable;
            buildingProjectTable.data(buildingProjectDS.cursor());
            buildingProjectDS.refresh();
            buildingProjectDS.research(true);
        }
    }
}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    Common                  locCommon;

    Query                   locQuery;
    QueryBuildDataSource    locQbds;
    QueryBuildDataSource    locQbdsBase;
    QueryBuildRange         locQbr;
    str                     queryCondition;

    smmBusRelTable          locSmmBusRelTable;

    if(element.args())
    {
        frmArgs = new Args();
        frmArgs = element.args();

        if(frmArgs.record())
        {
            locCommon = frmArgs.record();

            switch(locCommon.TableId)
            {
                case Tablenum(KCS_KBVBuildingProjectTable):
                    frmKCS_KBVBuildingProjectTable  = locCommon;
                    break;

                case Tablenum(KCS_KBVRequestTable):
                    frmKCS_KBVRequestTableToCopy    = locCommon;
                    frmKCS_KBVBuildingProjectTable  = KCS_KBVBuildingProjectTable::find(frmKCS_KBVRequestTableToCopy.KCS_KBVBuildingProjectID);
                    break;

                case Tablenum(smmBusRelTable):
                    locSmmBusRelTable               = locCommon;
                    break;
            }
        }

    }

    super();

    frmHCMWorkerRecId   = HcmWorkerLookup::currentWorker();
    /*
    this.queryBuildDataSource().sortClear();
    this.queryBuildDataSource().addSortField(fieldNum(KCS_KBVRequestTable, KCS_KBVRequestID), SortOrder::Descending);
    */
    locQuery = this.query();

    switch (frmArgs.menuitemName())
    {
        case menuItemDisplayStr(AVAKBVRequestTable):
            if(frmKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID)
            {
                locQbr      = locQuery.dataSourceTable(tableNum(KCS_KBVRequestTable)).addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestID));
                locQbr.value(queryValue(frmKCS_KBVRequestTableToCopy.KCS_KBVRequestID));
            }
            break;

        case menuItemDisplayStr(AVAKBVRequestTableBP):
            if(frmKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID)
            {
                locQbr      = locQuery.dataSourceTable(tableNum(KCS_KBVRequestTable)).addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVBuildingProjectID));
                locQbr.value(queryValue(frmKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID));
            }
            break;
        /*
        case menuItemDisplayStr(AVAKBVRequestTableAll):
            if(frmKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID)
            {
                //locQbr      = locQuery.dataSourceTable(tableNum(KCS_KBVRequestTable)).addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVBuildingProjectID));
                //locQbr.value(queryValue(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID));
            }
            break;

        case menuItemDisplayStr(AVAKBVRequestTableCopyToUC):
            if(frmKCS_KBVRequestTableToCopy.Recid)
            {
                //KCS_KBVRequestTable_DS.crossCompanyAutoQuery(false);
                //KCS_KBVRequestTable_DS.research();
                //KCS_KBVRequestTable.clear();
                //KCS_KBVRequestTable.initValueCopyToUC(kcs_KBVRequestTableToCopy, curExt());  //ToDo: replace curExt() with target UC
            }
            break;
        */
        case menuItemDisplayStr(AVAKBVRequestTableNotAssigned):
            locQbds = SysQuery::findOrCreateDataSource(locQuery, tableNum(KCS_KBVRequestTable));
            SysQuery::findOrCreateRange(locQbds, fieldNum (KCS_KBVRequestTable, AVAWorkerSalesTaker)).value(queryValue(0));
            SysQuery::findOrCreateRange(locQbds, fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus)).value(queryValue(KCS_KBVRequestStatus::Created));
            /*if (element.args().callerName() == formStr(AVABuildingProjectsAndSalesQuotations))
            {
                SysQuery::findOrCreateRange(locQbds, fieldNum (KCS_KBVRequestTable, KCS_KBVDeliveryDate)).value(SysQueryRangeUtil::lessThanDate());
            }  */
            /*
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, AVAWorkerSalesTaker));
            locQbr.value(queryValue(0));
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus));
            locQbr.value(queryValue(KCS_KBVRequestStatus::Created));
            */
            break;

        case menuItemDisplayStr(AVAKBVRequestTableNotAssignedDueDisplay):
            locQbds = SysQuery::findOrCreateDataSource(locQuery, tableNum(KCS_KBVRequestTable));
            SysQuery::findOrCreateRange(locQbds, fieldNum (KCS_KBVRequestTable, AVAWorkerSalesTaker)).value(queryValue(0));
            SysQuery::findOrCreateRange(locQbds, fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus)).value(queryValue(KCS_KBVRequestStatus::Created));
            SysQuery::findOrCreateRange(locQbds, fieldNum (KCS_KBVRequestTable, KCS_KBVDeliveryDate)).value(SysQueryRangeUtil::lessThanDate());
            /*
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, AVAWorkerSalesTaker));
            locQbr.value(queryValue(0));
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus));
            locQbr.value(queryValue(KCS_KBVRequestStatus::Created));
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVDeliveryDate));
            locQbr.value(SysQueryRangeUtil::lessThanDate());
            */
            break;

        case menuItemDisplayStr(AVAKBVRequestTableMyOpen):
            locQbds = SysQuery::findOrCreateDataSource(locQuery, tableNum(KCS_KBVRequestTable));
            /* creates or relation so no not()
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus));
            locQbr.value(SysQuery::valueNot(KCS_KBVRequestStatus::Refused));
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus));
            locQbr.value(SysQuery::valueNot(KCS_KBVRequestStatus::Answered));
            */
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus));
            locQbr.value(SysQuery::value(KCS_KBVRequestStatus::Created));
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus));
            locQbr.value(SysQuery::value(KCS_KBVRequestStatus::Assigned));
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus));
            locQbr.value(SysQuery::value(KCS_KBVRequestStatus::InProcess));
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, AVAWorkerSalesTaker));
            locQbr.value(queryValue(frmHCMWorkerRecId));
            //locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVModifiedBy));
            //locQbr.value(queryValue(0));
            break;

        case menuItemDisplayStr(AVAKBVRequestTableMyOpenTileDisplay):
        case menuItemDisplayStr(AVAKBVRequestTableMyOpenWorkerTileDisplay):
            locQbds = SysQuery::findOrCreateDataSource(locQuery, tableNum(KCS_KBVRequestTable));
            //locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus));
            //locQbr.value(SysQuery::valueNot(KCS_KBVRequestStatus::Refused));
            //locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, AVAWorkerSalesTaker));
            //locQbr.value(queryValue(frmHCMWorkerRecIdCallerFilter));
            //locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVModifiedBy));
            //locQbr.value(queryValue(0));
            break;

        case menuItemDisplayStr(AVAKBVRequestTableMyClosed):
            queryCondition  = '(%1 != %2)';
            locQbds = SysQuery::findOrCreateDataSource(locQuery, tableNum(KCS_KBVRequestTable));
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, AVAWorkerSalesTaker));
            locQbr.value(queryValue(frmHCMWorkerRecId));
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestStatus));
            locQbr.value(SysQuery::value(KCS_KBVRequestStatus::Answered));
            /*
            locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVModifiedBy));
            locQbr.value(   strFmt( queryCondition,
                            fieldStr (KCS_KBVRequestTable, KCS_KBVModifiedBy),
                            queryValue('0') )   );
            */
            //locQbr  = locQbds.addRange(fieldNum (KCS_KBVRequestTable, KCS_KBVModifiedBy));
            //locQbr.value(SysQuery::valueNot(0));
            break;

        case menuItemDisplayStr(AVAKBVRequestTableSmmBusRelTable):
            if(locSmmBusRelTable.RecId)
            {
                locQbdsBase = locQuery.dataSourceTable(tableNum(KCS_KBVRequestTable));
                locQbds     = locQbdsBase.addDataSource(tableNum(AVABPInquirerRequestDirPartyIdView));
                locQbds.joinMode(JoinMode::ExistsJoin);
                locQbds.addLink(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestID),
                                fieldNum (AVABPInquirerRequestDirPartyIdView, ID),
                                locQbdsBase.name()  );
                locQbr      = locQbds.addRange(fieldNum (AVABPInquirerRequestDirPartyIdView, DirPartyId));
                locQbr.value(queryValue(locSmmBusRelTable.Party));

                /*
                locQbds     = locQbdsBase.addDataSource(tableNum(KCS_KBVInquirerOfTheRequest));
                locQbds.joinMode(JoinMode::ExistsJoin);
                locQbds.addLink(fieldNum (KCS_KBVRequestTable, KCS_KBVRequestID),
                                fieldNum (KCS_KBVInquirerOfTheRequest, KCS_KBVRequestID),
                                locQbdsBase.name()  );
                locQbr      = locQbds.addRange(fieldNum (KCS_KBVInquirerOfTheRequest, DirPartyId));
                locQbr.value(queryValue(locSmmBusRelTable.Party));
                */
            }
            break;

    }
}

/// <summary>
///    AVA <c>create</c> method.
/// </summary>
/// <param name="_append">
///    <c>boolean</c> as type
/// </param>
public void create(boolean _append = false)
{
    KCS_KBVRequestTable locKCS_KBVRequestTable;

    super(_append);

    switch (frmArgs.menuitemName())
    {
        case menuItemDisplayStr(AVAKBVRequestTableCopyToUC):
            if(frmKCS_KBVRequestTableToCopy.Recid && frmDataAreaIdCopyTo != '')
            {
                changecompany(frmDataAreaIdCopyTo)
                {
                    //locKCS_KBVRequestTable.selectforupdate(true);
                    locKCS_KBVRequestTable.clear();
                    locKCS_KBVRequestTable.initValue();
                    locKCS_KBVRequestTable.initValueCopyToUC(frmKCS_KBVRequestTableToCopy, frmDataAreaIdCopyTo);
                    locKCS_KBVRequestTable.insert();
                }

                //KCS_KBVRequestTable.clear();
                //KCS_KBVRequestTable.initValueCopyToUC(frmKCS_KBVRequestTableToCopy, frmDataAreaIdCopyTo);
            }
            break;
    }
}

/// <summary>
///    AVA <c>active</c> method.
/// </summary>
/// <returns>
///    <c>int</c> as return value
/// </returns>
public int active()
{
    int ret;

    ret = super();

    if(KCS_KBVRequestTable.AVAWorkerSalesTaker != frmHCMWorkerRecId)
    {
        AVAKBVRequestIWillDoIt.enabled(true);
        AVAKBVRequestIDoNotDo.enabled(false);
    }
    else
    {
        AVAKBVRequestIWillDoIt.enabled(false);
        AVAKBVRequestIDoNotDo.enabled(true);
    }

    element.addSecondaryDataAreaInfomation();

    return ret;
}

edit ContactPersonName editContactPersonName_KCS_KBVRequestTable(   boolean             _set,
                                                                    KCS_KBVRequestTable _record,
                                                                    ContactPersonName   _name)
{
    ContactPersonName   retVal;

    if (_set)
    {
        AVAKBVDirPartyContactPersonHelper   locAVAKBVDirPartyContactPersonHelper;

        locAVAKBVDirPartyContactPersonHelper = new AVAKBVDirPartyContactPersonHelper();

        locAVAKBVDirPartyContactPersonHelper.parmSet(_set);
        locAVAKBVDirPartyContactPersonHelper.parmDataAreaId(frmDataAreaId);
        locAVAKBVDirPartyContactPersonHelper.parmDirPartyId(GridHeader_DirPartyId.value());
        locAVAKBVDirPartyContactPersonHelper.parmDirPartyName('');
        locAVAKBVDirPartyContactPersonHelper.parmContactPersonId(_name);
        locAVAKBVDirPartyContactPersonHelper.parmContactPersonName(ContactPerson::find(_name).personName());

        retVal = locAVAKBVDirPartyContactPersonHelper.getEditContactPersonName();
        retVal = locAVAKBVDirPartyContactPersonHelper.getEditContactPersonNameModified();

        GridHeader_DirPartyId.value(locAVAKBVDirPartyContactPersonHelper.parmDirPartyId());
        GridHeader_ContactPersonId.Text(locAVAKBVDirPartyContactPersonHelper.parmContactPersonId());
        GridHeader_editContactPersonName.text(locAVAKBVDirPartyContactPersonHelper.parmContactPersonName());
        KCS_KBVRequestTable.DirPartyId      = locAVAKBVDirPartyContactPersonHelper.parmDirPartyId();
        KCS_KBVRequestTable.ContactPersonId = locAVAKBVDirPartyContactPersonHelper.parmContactPersonId();
        KCS_KBVSearchTable::setFromCommonField(KCS_KBVRequestTable.KCS_KBVBuildingProjectID,KCS_KBVRequestTable,fieldNum(KCS_KBVRequestTable,ContactPersonId));

    }
    else
    {
        retVal = ContactPerson::find(_record.ContactPersonId).personName();
    }

    return retVal;

}

