/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    KCS_KBVRequestTable locKCS_KBVRequestTable;
    KCS_KBVDeliveryDate locKCS_KBVDeliveryDate;
    str                 locTitleStr;
    str                 locMessageStr;
    boolean             locRequestInSecondayryDataAreaExist;

    super();

    if(     frmAVASecondaryDataAreaIdBPRequests != ''
        &&  frmAVAForceSecondaryRequest         == NoYes::Yes   )
    {
        locKCS_KBVDeliveryDate = SecondaryKCS_KBVDeliveryDate.dateValue();
        if(     locKCS_KBVDeliveryDate != dateNull() 
            &&  locKCS_KBVDeliveryDate <= frmToday  )
        {
            locTitleStr     = strFmt("@NDX:NXATakeOverNextRequestInSecondDA", frmAVASecondaryDataAreaIdBPRequests);
            locMessageStr   = strFmt("@NDX:NXATakeOverNextRequestInSecondDAHelp", frmAVASecondaryDataAreaIdBPRequests, locKCS_KBVDeliveryDate);
            Box::info(locMessageStr, locTitleStr);
            locRequestInSecondayryDataAreaExist = true;
        }
    }
    if(!locRequestInSecondayryDataAreaExist)
    {
        locKCS_KBVRequestTable = KCS_KBVRequestTable::getNextUnassignedRequest(frmHCMWorkerRecId);
        if(locKCS_KBVRequestTable.RecId)
        {
            /*
            // set filter to actual created request 
            //locsmmSalesUnit = smmSalesUnit::avaGetSalesUnitCurrentWorkerIndoor(frmHCMWorkerRecId, false);
            locsmmSalesUnit = smmSalesUnit::find(locKCS_KBVRequestTable.KCS_KBVSmmSalesUnitIndoor);
            if(locsmmSalesUnit.RecId)
            {
                KCS_KBVRequestTableFilterFields_KCS_KBVSmmSalesUnitIndoor.text(locsmmSalesUnit.SalesUnitId);
                KCS_KBVRequestTableFilterFields_KCS_KBVSmmSalesUnitIndoor.modified();
            }
            */
            if(!locKCS_KBVRequestTable.AVAWorkerSalesTaker && frmHCMWorkerRecId)
            {
                locKCS_KBVRequestTable.assignUnassignRequest(frmHCMWorkerRecId);
                locKCS_KBVRequestTable.assignUnassignRelatedRequests();
            }
            KCS_KBVRequestTable_DS.executeQuery();
        }
        else        
        {
            locKCS_KBVRequestTable.assignUnassignRequestInfo();
        }
    }

}

