/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    KCS_KBVRequestTable     locKCS_KBVRequestTable;
    MultiSelectionHelper    helper;

    HCMWorkerRecId          locHCMWorkerRecId;
    smmSalesUnit            locsmmSalesUnit;

    helper              = MultiSelectionHelper::construct();

    locHCMWorkerRecId   = AVAKBVBuildingProjectHelper::dialogGetWorker();  //get Worker from Dialog

    // check chosen worker
    if(locHCMWorkerRecId)
    {
        locsmmSalesUnit = smmSalesUnit::avaGetSalesUnitCurrentWorkerIndoor(locHCMWorkerRecId, false, false);
        if(!locsmmSalesUnit.RecId)
        {
            error("@NDX:NXAChosenWorkerNotMemberOfIndoorSalesUnit");
            //locHCMWorkerRecId = 0;
            return;
        }
    }

    super();

    helper.parmDatasource(KCS_KBVRequestTable_DS);
    locKCS_KBVRequestTable = helper.getFirst();

    if(locHCMWorkerRecId)
    {
        /*
        for(locKCS_KBVRequestTable = KCS_KBVRequestTable_DS.getFirst(true) ? KCS_KBVRequestTable_DS.getFirst(true) : KCS_KBVRequestTable_DS.cursor();
            locKCS_KBVRequestTable;
            locKCS_KBVRequestTable = KCS_KBVRequestTable_DS.getNext())
        */
        while (locKCS_KBVRequestTable.RecId != 0)
        {
            if(locKCS_KBVRequestTable.dataAreaId == curExt())
            {
                locKCS_KBVRequestTable.selectForUpdate(true);

                locKCS_KBVRequestTable.AVAWorkerSalesTaker      = locHCMWorkerRecId;
                locKCS_KBVRequestTable.AVAWorkerSalesTakerDate  = frmToday;
                if(locKCS_KBVRequestTable.KCS_KBVRequestStatus == KCS_KBVRequestStatus::Created)
                {
                    locKCS_KBVRequestTable.KCS_KBVRequestStatus = KCS_KBVRequestStatus::Assigned;
                }

                ttsbegin;
                locKCS_KBVRequestTable.update();
                locKCS_KBVRequestTable.assignUnassignRelatedRequests(locHCMWorkerRecId);
                ttscommit;
            }
            locKCS_KBVRequestTable = helper.getNext();
        }
        KCS_KBVRequestTable_DS.research(true);
    }
}

/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    AVAReason           locAVAReason;

    KCS_KBVRequestTable     locKCS_KBVRequestTable;
    MultiSelectionHelper    helper;

    HCMWorkerRecId          locHCMWorkerRecId;

    helper              = MultiSelectionHelper::construct();

    super();

    locAVAReason = AVAKBVBuildingProjectHelper::dialogGetReason();

    helper.parmDatasource(KCS_KBVRequestTable_DS);
    locKCS_KBVRequestTable = helper.getFirst();

    while (locKCS_KBVRequestTable.RecId != 0)
    {
        if(locKCS_KBVRequestTable.dataAreaId == curExt() && locKCS_KBVRequestTable.AVAWorkerSalesTaker)
        {
            locHCMWorkerRecId = locKCS_KBVRequestTable.AVAWorkerSalesTaker;

            locKCS_KBVRequestTable.assignUnassignRequest(0, locAVAReason);
            //locKCS_KBVRequestTable.assignUnassignRelatedRequests(0, locHCMWorkerRecId, locAVAReason);
        }
        locKCS_KBVRequestTable = helper.getNext();
    }
    KCS_KBVRequestTable_DS.executeQuery();
}

