public void clicked()
{
    smmBusRelTable  smmBusRelTable;
    Args            locArgs;
    Args            locArgsService;
    MenuFunction    menuFunction;

    super();

    locArgs             = new Args();

    changecompany(frmDataAreaId)
    {
        smmBusRelTable  = smmBusRelTable::findByParty(KCS_KBVInquirerOfTheRequest.DirPartyId);
        locArgs.record(smmBusRelTable);
        locArgs.caller(this.formRun());
        locArgs.parmObject(this);

        // adHoc generation of missing contacts
        if(smmBusRelTable.RecId)
        {
            locArgsService = locArgs;
            locArgsService.menuItemType(MenuItemType::Action);
            locArgsService.menuItemName(menuItemActionStr(AVACreateContactPersonBasedOnGABBusRel));
            AVACreateContactPersonBasedOnGABController::main(locArgsService);
        }

        menuFunction    = new MenuFunction(menuitemDisplayStr(ContactPersonNewQuickCreate), MenuItemType::Display);

        if (menuFunction && menuFunction.checkAccessRights())
        {
            menuFunction.run(locArgs);
        }
    }
}

